ALTER TABLE `Item` MODIFY COLUMN `lpcColor` varchar(32);
ALTER TABLE `ItemVariant` MODIFY COLUMN `lpcColor` varchar(32);
ALTER TABLE `Item` ADD `lpcMaterialColors` json;
ALTER TABLE `ItemVariant` ADD `lpcMaterialColors` json;

UPDATE `GameAsset`
SET `lpcConfig` = JSON_SET(
  JSON_REMOVE(`lpcConfig`, '$.replacementSlot'),
  '$.version', 2,
  '$.replacementSlots', CASE
    WHEN COALESCE(JSON_UNQUOTE(JSON_EXTRACT(`lpcConfig`, '$.replacementSlot')), 'none') = 'none' THEN JSON_ARRAY()
    ELSE JSON_ARRAY(JSON_UNQUOTE(JSON_EXTRACT(`lpcConfig`, '$.replacementSlot')))
  END,
  '$.upstream', JSON_ARRAY()
)
WHERE `type` = 'LPC' AND `lpcConfig` IS NOT NULL AND JSON_EXTRACT(`lpcConfig`, '$.version') = 1;


